<script setup lang="ts">
import { onMounted, ref } from "vue"; import { useRouter } from "vue-router"; import { createRepair, listCustomers } from "../api";
const router = useRouter(); const customers = ref<{ id: string; displayName: string }[]>([]); const form = ref({ customerId: "", deviceType: "", brand: "", model: "", serialNumber: "", reportedIssue: "", deliveredAccessories: "" }); const error = ref(""); onMounted(async () => { customers.value = await listCustomers(); }); async function save() { try { const repair = await createRepair(form.value); void router.push({ name: "repairs.detail.general", params: { id: repair.id } }); } catch (reason) { error.value = (reason as Error).message; } }
</script>
<template><form class="entity-form" @submit.prevent="save"><header><div><p class="eyebrow">Taller</p><h1>Nueva reparacion</h1></div></header><fieldset><legend>Equipo y cliente</legend><label>Cliente<select v-model="form.customerId" required><option disabled value="">Selecciona un cliente</option><option v-for="customer in customers" :key="customer.id" :value="customer.id">{{ customer.displayName }}</option></select></label><label>Tipo de equipo<input v-model="form.deviceType" required /></label><label>Marca<input v-model="form.brand" required /></label><label>Modelo<input v-model="form.model" required /></label><label>Numero de serie<input v-model="form.serialNumber" /></label></fieldset><fieldset><legend>Recepcion</legend><label>Averia reportada<textarea v-model="form.reportedIssue" required rows="4" /></label><label>Accesorios entregados<input v-model="form.deliveredAccessories" /></label></fieldset><p v-if="error" class="feedback error">{{ error }}</p><footer><button class="secondary" type="button" @click="router.back()">Cancelar</button><button>Crear orden</button></footer></form></template>